<?php

namespace App\Restaurant\Repository;
use App\Business\Entity\BusinessInvoice;
use Doctrine\ORM\EntityRepository;


/**
 * ProductionElementRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class RestaurantProductionExpenseRepository extends EntityRepository
{
    public function removeProductionExpense(BusinessInvoice $invoice)
    {
        $em = $this->getEntityManager();

	    if(!empty($invoice->getBusinessInvoiceParticulars())) {

		    /* @var  $item BusinessInvoiceParticular */

		    foreach ($invoice->getBusinessInvoiceParticulars() as $item) {
			    $transaction = $em->createQuery( "DELETE App\\Business\\Entity\\BusinessProductionExpense e WHERE e.businessInvoiceParticular ={$item->getId()}");
			    if($transaction){
                    $transaction->execute();
                }
		    }

	    }
	}

}
